        &system_instruction::assign(pool_onramp_info.key, stake_program_info.key),
        core::slice::from_ref(pool_onramp_info),
        onramp_signers,
    )?;

    invoke_signed(
        &stake::instruction::initialize_checked(pool_onramp_info.key, &authorized),
